// Twisted McKay-Thompson series Z(g,h; tau) head data for a small subset of commuting pairs.
// Source: Norton (1984), Carnahan (2010), Mason - the values shown below are the leading
// q-coefficients of the head of each Z. For pure twists g != e, the q-grading is 1/|g|-fractional.
const PAIRS = {
  "e,e": {
    label: "Z(e,e; τ) = J(τ) = j(τ) − 744",
    grp:   "SL_2(ℤ)  (genus 0)",
    head:  "q^{-1} + 0 + 196884 q + 21493760 q^2 + 864299970 q^3 + ...",
    note:  "the diagonal: ordinary moonshine module character.",
  },
  "e,2A": {
    label: "Z(e,2A; τ) = T_{2A}(τ)",
    grp:   "Γ₀(2)+   (genus 0)",
    head:  "q^{-1} + 0 + 4372 q + 96256 q^2 + 1240002 q^3 + ...",
    note:  "first column g = e is the ordinary Thompson series of h.",
  },
  "2A,e": {
    label: "Z(2A,e; τ) = trace on the 2A-twisted module of V^♮",
    grp:   "Γ₀(2)    (genus 0)",
    head:  "q^{-1/2} + 4372 q^{1/2} + 96256 q^{3/2} + ...",
    note:  "PURE TWIST: the q-grading is now half-integer (since |2A| = 2);\nthe SL_2(ℤ) action mixes 2A-twist with 2A-action.",
  },
  "2A,2A": {
    label: "Z(2A,2A; τ)",
    grp:   "Γ₀(2)+ (or a small index subgroup; genus 0)",
    head:  "q^{-1/2} − 4372 q^{1/2} + 96256 q^{3/2} − ...",
    note:  "diagonal commuting pair. Z(2A,2A;τ+1) = Z(2A·2A, 2A; τ) = Z(e,2A; τ)\nby T-action — used as a consistency check.",
  },
  "2A,2B": {
    label: "Z(2A,2B; τ)",
    grp:   "genus 0 with cocycle",
    head:  "q^{-1/2} + 0 q^{1/2} + ...   (vanishing first ramified coefficient)",
    note:  "2A and 2B commute inside ℳ (centralizer C_ℳ(2A) ⊃ a 2-Sylow of 2B's normalizer).\nThe vanishing trace tracks the +1/-1 split of 2A on V^♮.",
  },
  "3A,3A": {
    label: "Z(3A,3A; τ)",
    grp:   "Γ₀(3)+ extension; genus 0",
    head:  "q^{-1/3} + 783 q^{2/3} − 8672 q^{5/3} + ...   (cube-root grading)",
    note:  "order-3 twist gives 1/3-fractional q-grading; cocycle is a 3rd root of unity.",
  },
  "3A,e": {
    label: "Z(3A,e; τ)",
    grp:   "Γ₀(3)    (genus 0)",
    head:  "q^{-1/3} + 783 q^{2/3} + 8672 q^{5/3} + ...",
    note:  "the 3A-twisted module's bare graded dimension; tau-translated by S→ (e,3A) Thompson series.",
  },
};
const sel = $('#w-gen-pair'), out = $('#w-gen-out');
let history = [];
function display(currentKey, hist){
  const r = PAIRS[currentKey];
  let s = r.label + '\n';
  s += '  modular group:   ' + r.grp + '\n';
  s += '  q-expansion:     ' + r.head + '\n';
  s += '  note:            ' + r.note + '\n';
  if(hist && hist.length){
    s += '\n  SL_2(ℤ) history (acts on (g,h) by  (g,h) → (g^a h^c, g^b h^d)):\n';
    hist.forEach((h,i)=>{ s += '    ' + (i+1) + '. ' + h + '\n'; });
  }
  s += '\n';
  s += '  general fact (Norton, proved by Carnahan):\n';
  s += '    Z(g, h; τ) is constant or a Hauptmodul for a genus-0 Γ_{g,h} ≤ SL_2(ℝ).\n';
  s += '    Z(g, h; (a τ + b)/(c τ + d)) = ζ · Z(g^a h^c, g^b h^d; τ),  ζ a 24th root of unity.\n';
  s += '    Z(e, h; τ)  recovers the ordinary Thompson series  T_h(τ).';
  out.textContent = s;
}
function applyS(key){
  // S sends (g,h) → (h, g^{-1}); for our limited table we approximate symbolically.
  const m = { "e,e":"e,e", "e,2A":"2A,e", "2A,e":"e,2A",
              "2A,2A":"2A,2A", "2A,2B":"2B,2A_{not_in_table}",
              "3A,3A":"3A,3A", "3A,e":"e,3A_{not_in_table}" };
  return m[key] || key;
}
function applyT(key){
  // T sends (g,h) → (g, gh).  For our involution-heavy table 2A·2A = e, 3A·3A = 3A^{-1} = 3A^2.
  const m = { "e,e":"e,e", "e,2A":"e,2A", "2A,e":"2A,2A",
              "2A,2A":"2A,e", "2A,2B":"2A,2A·2B_{not_in_table}",
              "3A,3A":"3A,3A^2_{not_in_table}", "3A,e":"3A,3A" };
  return m[key] || key;
}
